-- Exact live public weapon source snapshot, SELECT-only, md5 14433e4e379ae811edd9d9d8345711f8
CREATE OR REPLACE FUNCTION public.encounter_weapon_attack_v1(p_attacker_id uuid, p_target_id uuid, p_inventory_item_id uuid, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
declare
  v_uid uuid:=auth.uid(); v_role text:=coalesce(auth.role(),''); v_a public.encounter_participants%rowtype; v_t public.encounter_participants%rowtype; v_e public.encounters%rowtype;
  v_existing public.encounter_command_requests%rowtype; v_profile jsonb; v_targeting jsonb; v_damage_result jsonb; v_attack_roll jsonb;
  v_inserted integer:=0; v_dist_ft integer; v_reach integer; v_normal integer; v_long integer; v_is_ranged boolean; v_is_thrown boolean; v_long_disadvantage boolean:=false; v_base_disadvantage boolean:=false; v_disadvantage boolean:=false; v_advantage boolean:=false;
  v_roll integer; v_roll2 integer; v_total integer; v_target_ac integer; v_hit boolean; v_crit boolean; v_dice_count integer; v_die_size integer; v_i integer; v_damage_roll integer:=0; v_raw_damage integer:=0; v_ability_mod integer; v_magic_bonus integer; v_result jsonb;
begin
  if p_attacker_id is null or p_target_id is null or p_inventory_item_id is null or p_request_id is null then raise exception 'Attacker, target, equipped weapon and request id are required'; end if;
  if p_attacker_id=p_target_id then raise exception 'Attacker and target must differ'; end if;
  insert into public.encounter_command_requests(request_id,encounter_id,participant_id,command_type,requested_by) select p_request_id,p.encounter_id,p.id,'weapon_attack',v_uid from public.encounter_participants p where p.id=p_attacker_id on conflict(request_id) do nothing; get diagnostics v_inserted=row_count;
  if v_inserted=0 then select * into v_existing from public.encounter_command_requests where request_id=p_request_id; if not found or v_existing.command_type<>'weapon_attack' or v_existing.participant_id<>p_attacker_id then raise exception 'Request id is already used for another command'; end if; return coalesce(v_existing.result,jsonb_build_object('duplicate',true,'pending',true)); end if;
  select * into v_a from public.encounter_participants where id=p_attacker_id for update; if not found then raise exception 'Attacker not found'; end if;
  select * into v_t from public.encounter_participants where id=p_target_id and encounter_id=v_a.encounter_id for update; if not found then raise exception 'Target not found in this encounter'; end if;
  select * into v_e from public.encounters where id=v_a.encounter_id for update; if not found then raise exception 'Encounter not found'; end if;
  if v_e.status<>'active' or v_e.active_participant_id is distinct from v_a.id then raise exception 'It is not this participant''s active turn'; end if;
  if v_role<>'service_role' and not public.encounter_can_control_participant_v1(v_a.id) then raise exception 'Not authorized to control this participant'; end if;
  if v_a.is_defeated then raise exception 'Defeated participants cannot attack'; end if; if v_t.is_defeated then raise exception 'Target is already defeated'; end if; if not v_a.action_available then raise exception 'Action already spent'; end if;
  v_profile:=public.encounter_weapon_profile_internal_v1(v_a.id,p_inventory_item_id); if v_profile is null then raise exception 'Selected weapon is not currently equipped or has no supported canonical attack profile'; end if;
  v_targeting:=public.encounter_targeting_context_internal_v1(v_a.id,v_t.id); if not coalesce((v_targeting->>'hasLineOfSight')::boolean,false) then raise exception 'Target is blocked by total cover or line-of-sight obstruction'; end if;
  v_dist_ft:=coalesce((v_targeting->>'distanceFt')::integer,0); v_reach:=coalesce((v_profile->>'reachFt')::integer,5); v_normal:=coalesce((v_profile->>'normalRangeFt')::integer,v_reach); v_long:=coalesce((v_profile->>'longRangeFt')::integer,v_normal); v_is_ranged:=coalesce((v_profile->>'isRanged')::boolean,false); v_is_thrown:=coalesce((v_profile->>'isThrown')::boolean,false);
  if v_is_ranged then if v_dist_ft>v_long then raise exception 'Target is beyond the weapon''s long range'; end if; v_long_disadvantage:=v_dist_ft>v_normal; elsif v_dist_ft<=v_reach then v_long_disadvantage:=false; elsif v_is_thrown then if v_dist_ft>v_long then raise exception 'Target is beyond the thrown weapon''s long range'; end if; v_long_disadvantage:=v_dist_ft>v_normal; else raise exception 'Target is beyond this weapon''s reach'; end if;
  v_base_disadvantage:=coalesce(v_t.dodging,false) or v_long_disadvantage; v_attack_roll:=private.encounter_resolve_attack_roll_v1(v_a.id,v_t.id,v_base_disadvantage); v_roll:=coalesce((v_attack_roll->>'roll')::integer,1); v_roll2:=nullif(v_attack_roll->>'secondRoll','')::integer; v_advantage:=coalesce((v_attack_roll->>'advantage')::boolean,false); v_disadvantage:=coalesce((v_attack_roll->>'disadvantage')::boolean,false);
  v_total:=v_roll+coalesce((v_profile->>'attackBonus')::integer,0); v_target_ac:=coalesce(v_t.armor_class,10)+coalesce((v_targeting->>'coverAcBonus')::integer,0); v_crit:=v_roll=20; v_hit:=case when v_roll=1 then false when v_crit then true else v_total>=v_target_ac end;
  v_dice_count:=split_part(v_profile->>'damageDice','d',1)::integer; v_die_size:=split_part(v_profile->>'damageDice','d',2)::integer; if v_crit then v_dice_count:=v_dice_count*2; end if;
  if v_hit then for v_i in 1..v_dice_count loop v_damage_roll:=v_damage_roll+floor(random()*v_die_size)::integer+1; end loop; v_ability_mod:=coalesce((v_profile->>'abilityMod')::integer,0); v_magic_bonus:=coalesce((v_profile->>'magicBonus')::integer,0); v_raw_damage:=greatest(0,v_damage_roll+v_ability_mod+v_magic_bonus); v_damage_result:=public.encounter_apply_damage_internal_v1(v_t.id,v_raw_damage,v_profile->>'damageType'); else v_damage_result:=jsonb_build_object('targetId',v_t.id,'damageType',v_profile->>'damageType','rawDamage',0,'resistant',false,'immune',false,'vulnerable',false,'damage',0,'targetHp',v_t.current_hp,'targetTempHp',v_t.temp_hp,'defeated',v_t.is_defeated); end if;
  update public.encounter_participants set action_available=false,updated_at=timezone('utc',now()) where id=v_a.id;
  v_result:=jsonb_build_object('requestId',p_request_id,'attackerId',v_a.id,'targetId',v_t.id,'inventoryItemId',p_inventory_item_id,'weapon',v_profile->>'name','distanceFt',v_dist_ft,'roll',v_roll,'secondRoll',v_roll2,'advantage',v_advantage,'disadvantage',v_disadvantage,'guidingBoltAdvantage',coalesce((v_attack_roll->>'guidingBoltAdvantage')::boolean,false),'guidingBoltEffectConsumed',coalesce((v_attack_roll->>'guidingBoltEffectConsumed')::boolean,false),'advantageCanceledByDisadvantage',coalesce((v_attack_roll->>'advantageCanceledByDisadvantage')::boolean,false),'longRangeDisadvantage',v_long_disadvantage,'dodging',v_t.dodging,'attackBonus',(v_profile->>'attackBonus')::integer,'total',v_total,'baseTargetAc',coalesce(v_t.armor_class,10),'coverAcBonus',(v_targeting->>'coverAcBonus')::integer,'targetAc',v_target_ac,'coverLevel',v_targeting->>'coverLevel','hit',v_hit,'critical',v_crit,'damageDice',v_profile->>'damageDice','damageRoll',v_damage_roll,'damageType',v_profile->>'damageType','rawDamage',v_raw_damage,'damage',(v_damage_result->>'damage')::integer,'resistant',(v_damage_result->>'resistant')::boolean,'immune',(v_damage_result->>'immune')::boolean,'vulnerable',(v_damage_result->>'vulnerable')::boolean,'targetHp',(v_damage_result->>'targetHp')::integer,'targetTempHp',(v_damage_result->>'targetTempHp')::integer,'defeated',(v_damage_result->>'defeated')::boolean,'targeting',v_targeting,'profile',v_profile,'attackRoll',v_attack_roll);
  insert into public.encounter_combat_log(encounter_id,round,turn_index,actor_participant_id,target_participant_id,event_type,summary,detail) values(v_e.id,v_e.round,v_e.turn_index,v_a.id,v_t.id,'weapon_attack',v_a.display_name||case when v_hit then ' hit ' else ' missed ' end||v_t.display_name||' with '||(v_profile->>'name')||'.',v_result);
  update public.encounters set version=version+1,updated_at=timezone('utc',now()) where id=v_e.id; update public.encounter_command_requests set result=v_result where request_id=p_request_id; return v_result;
end;$function$;
